SELECT (SELECT AVG(mortality_rate) FROM acs_icu_patients_72_30_mortality) AS avg_mortality_rate, (SELECT AVG(survival_length_of_stay) FROM acs_icu_patients_72_30_survival) AS avg_survival_length_of_stay, (SELECT AVG(cardiac_complications_rate) FROM acs_icu_patients_72_30_complications_rate) AS avg_cardiac_complications_rate, (SELECT AVG(neurologic_complications_rate) FROM acs_icu_patients_72_30_complications_rate) AS avg_neurologic_complications_rate, (SELECT percentile_cont(0.75) within GROUP (ORDER BY survival_rate) FROM acs_icu_patients_72_30_survival_rate) AS survival_percentile_75 FROM acs_icu_patients_72_30;